CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,email TEXT UNIQUE NOT NULL,name TEXT NOT NULL,password_hash TEXT NOT NULL,currency TEXT NOT NULL DEFAULT 'NGN',theme TEXT NOT NULL DEFAULT 'system',reset_hash TEXT,reset_exp TIMESTAMP,created_at TIMESTAMP NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS expenses(id SERIAL PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,amount NUMERIC(14,2) NOT NULL,category TEXT NOT NULL,date DATE NOT NULL,notes TEXT NOT NULL DEFAULT '',created_at TIMESTAMP NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS expenses_user_date ON expenses(user_id,date);
CREATE TABLE IF NOT EXISTS budgets(user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,category TEXT NOT NULL,monthly_limit NUMERIC(14,2) NOT NULL,PRIMARY KEY(user_id,category));
CREATE TABLE IF NOT EXISTS revoked_tokens(jti TEXT PRIMARY KEY,expires_at TIMESTAMP NOT NULL);
